  ('ng-ex9-behemoth-super-explorer', 'Pilot''s Deck/Bridge (1, front, center)', 300, 'Can be sealed off behind an airtight hatch (120 M.D.C.) if breached.', 19),
  ('ng-ex9-behemoth-super-explorer', 'Main Body', 700, 'Reduced to zero, the robot shuts down and is useless.', 20),
  ('ng-v50-bigfoot', 'Main Guns: Plasma Cannons (2)', 220, 'Each. Small target: Called Shot, -3 to strike.', 1),
  ('ng-v50-bigfoot', 'Laser Cannon Turret (1, top)', 150, 'Small target: Called Shot, -3 to strike.', 2),
  ('ng-v50-bigfoot', 'Radar & Communications Dish (1, right side)', 90, 'Small target: Called Shot, -3 to strike.', 3),
  ('ng-v50-bigfoot', 'Short-Range Missile Box Launcher (1, right side)', 130, 'Small target: Called Shot, -3 to strike.', 4),
  ('ng-v50-bigfoot', 'Mini-Missile Tube Launchers (4, under main guns)', 12, 'Each. Small target: Called Shot, -3 to strike.', 5),
