INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-v36-beachmaster', 1, 'Blue-Green Chest Lasers (2)', '4D6 M.D. per blast; 1D4x10+4 M.D. per simultaneous dual blast at one target', 1, '1,200 ft (366 m) underwater; 2,000 ft (610 m) on land', 'Each single or dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel, secondarily defense. Chest-mounted pair; the robot''s only energy weapons, and they work under water.'),
  ('ng-v36-beachmaster', 2, 'Shoulder Mounted Mini-Torpedo Launcher (1)', 'Varies by torpedo; usually armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.), or a mix', 1, 'About one mile (1.6 km)', 'One at a time or volleys of two, four or eight', '16 mini-torpedoes', NULL, 'Anti-armor, secondarily anti-ship. Turret over the right shoulder, 360 degree rotation and 90 degree vertical arc; fires submerged, on the surface, or from beside or above the water, the torpedo dropping in and running at the target.'),
  ('ng-v36-beachmaster', 3, 'Shoulder Mounted Mini-Missile Launchers (2)', 'Varies by missile; plasma (1D6x10 M.D.) is standard', 1, 'One mile (1.6 km); a third of that fired underwater, and -3 to strike underwater or surface targets when fired from below the waves', 'One at a time or volleys of two, four or six', 'Six, three in each shoulder', NULL, 'Anti-armor, secondarily anti-ship.'),
  ('ng-v36-beachmaster', 4, 'Heavy Flamethrower', '1D4x10 M.D. to the target and everyone within 10 ft (3 m); 5D6 M.D. on diesel or gasoline', 1, '400 ft (122 m)', 'Each burst counts as one melee action/attack', 'About 48 bursts from an 80 gallon (302 liter) reserve; refuel with military napalm, or diesel or gasoline at reduced damage', NULL, 'Anti-structure, secondarily anti-personnel. Right arm. Waterproof and usable on the surface, but valves seal it shut when submerged. Anyone caught by it in a bunker, cave or unsealed vehicle without environmental gear or air must save vs poison or fall unconscious for 1D4 melee rounds.'),
  ('ng-v36-beachmaster', 5, 'M.D. Chainsaw (1, left forearm)', '5D6 M.D. per attack running; switched off, 1D4 M.D. plus robot P.S. punch damage when slashing', 1, 'Melee', NULL, 'Effectively unlimited', NULL, 'Boarding ships, anti-fortification and sabotage, secondarily melee and anti-personnel. Locks along the forearm for slashing and backhands, or slides forward past the hand to be used like a short sword. A modular unit: a silver-toothed saw can be swapped in against creatures vulnerable to silver, but its plating is spent once it has struck M.D.C. armor 2D4 times.'),
  ('ng-v36-beachmaster', 6, 'Electric Field Antenna', 'None; stuns, rolled on a table', 0, 'The water around the robot', 'Each activation counts as one melee action/attack', NULL, NULL, 'A thin antenna along the back that charges the surrounding water to drive off sharks and sea monsters. Water only; no effect on torpedoes or craft. Percentile roll per activation: 01-20 no effect; 21-40 target loses 1 attack this round and initiative; 41-60 loses 2 attacks and initiative; 61-80 loses all attacks this round and is -6 initiative next round; 81-00 cannot attack or move for 1D4 melee rounds. +10% against normal sharks, fish and sea life; -10% against dolphins, whales, large sea monsters and M.D. animals; -25% against truly massive sea monsters.'),
  ('ng-v36-beachmaster', 7, 'NG-505 Heavy Rail Cannon', '2D4x10 M.D.', 1, '4,000 ft (1,220 m)', 'Each shot counts as one melee attack', '90 round drum', NULL, 'Optional. The Ship Hunter variant carries it in place of the mini-torpedo launcher; anti-ship and anti-sea monster, secondarily anti-armor. Useless underwater, leaving only the chest lasers when submerged.'),
  ('ng-ex5-behemoth-explorer', 1, 'Mini-Missile Forearm Launchers (2)', 'Any mini-missile; standard issue is fragmentation (5D6 M.D.) and plasma (1D6x10 M.D.)', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3 or 4; a single missile or a volley counts as one melee attack', '48, 24 in each arm; hundreds more can be carried inside', NULL, 'Defense, secondarily anti-monster and anti-missile. Concealed on the side of each arm; the robot''s only weapons as built, though some owners add 2-6 rail guns or other turrets.'),
  ('ng-ex9-behemoth-super-explorer', 1, 'NG-X009 Rail Gun Turret (1)', '1D4x10 M.D. per 40 round burst', 1, '4,000 ft (1,219 m)', 'Each burst counts as one melee attack/action', '8,000 rounds (200 bursts) in two oversized detachable drums, reloaded from inside', NULL, 'Anti-armor, secondarily anti-aircraft. In the nose under the bridge; 180 degrees to either side and a 45 degree vertical arc; fired by the pilot or copilot. Its solid rounds ignore energy-reflecting armor and magic, and the Gunwolf''s monster-fighting ammunition can be loaded.'),
  ('ng-ex9-behemoth-super-explorer', 2, 'NG-437-TBL Triple Barrel Laser Turret (2, side)', '3D6 M.D. per single blast, 6D6 M.D. per double; 1D6x10+3 M.D. per simultaneous triple blast', 1, '2,000 ft (610 m)', 'A triple blast counts as TWO melee attacks', NULL, NULL, 'Defense and anti-aircraft, secondarily anti-monster and anti-personnel. Gun camera and laser targeting; 90 degree rotation and 90 degree vertical arc. Usually the dedicated gunner''s, but the copilot or communications officer can fire it. No payload is printed.'),
  ('ng-ex9-behemoth-super-explorer', 3, 'Concealed Missile Launcher (4)', 'By missile; standard mini-missile mix is 60% high explosive (1D4x10 M.D.), 30% plasma (1D6x10 M.D.) and 10% smoke', 1, 'By missile type', 'One at a time or volleys of two or four; a single missile or a volley counts as one melee attack', '128 mini-missiles (32 per launcher); or 32 short-range (8 per launcher); or 16 medium-range (4 per launcher)', NULL, 'Defense and anti-monster, secondarily anti-armor. A pair in the top of each front leg behind doors that close after each launch; fired by the gunner, pilot or copilot. Short-range launchers cost 500,000 credits more, medium-range one million. The features text on p.111 gives 16 short-range or 8 medium-range per leg, which agrees.'),
  ('ng-v50-bigfoot', 1, 'P-6040 "Magma" Plasma Cannons (2)', '1D6x10 M.D. per single blast; 2D6x10 M.D. per simultaneous dual blast at one target', 1, '2,000 ft (610 m)', 'Each single or double blast counts as one melee attack/action', 'Effectively unlimited', NULL, 'Anti-armor, secondarily anti-monster, anti-infantry and assault. A new, still somewhat experimental design; forward facing with a 30 degree vertical arc, aimed by turning the upper torso. Fired by the pilot, singly or linked.'),
  ('ng-v50-bigfoot', 2, 'Defensive Secondary Weapon System of Main Guns', 'By missile; typically high explosive (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'One mile (1.6 km)', 'One at a time or volleys of two or four', '8 mini-missiles, two in each of four tubes', NULL, 'Defense and anti-personnel, secondarily anti-missile and assault. Two mini-missile tube launchers under each cannon, for close attackers and missiles the laser misses; fired by the pilot.'),
  ('ng-v50-bigfoot', 3, 'NG-457-RFL Laser Cannon in Turret (1, top)', '3D6 M.D. per single blast; a carefully aimed four-blast burst at one target does 1D6x10+6 M.D. (TWO attacks); a hasty four-blast burst does 6D6 M.D. (one attack); a strafing burst hits 1D4 targets for 3D6 M.D. each', 1, '4,000 ft (1,219 m)', 'A single blast, a hasty burst or a strafing burst is one melee attack; a carefully aimed burst is two', 'Effectively unlimited', 'Strafing is shooting wild: -6 to strike and no strike bonuses', 'Defense and anti-aircraft, secondarily anti-personnel and assault. A four-barrel gatling laser in an open turret above and behind the main guns, turning 360 degrees with a 90 degree vertical arc independently of them. Strafing rolls one strike for the burst, then 1D4 for how many targets take a blast; against a single target only one blast lands. Misses can hit anything large directly behind the targets. The gunner is exposed and should wear heavy body armor or power armor.'),
  ('ng-v50-bigfoot', 4, 'Short-Range Missile Launcher (1, Right Side)', 'By missile; typically fragmentation (2D4x10 M.D., 20 ft/6.1 m radius), high explosive (2D6x10 M.D., 15 ft/4.6 m), armor piercing (2D6x10 M.D., 5 ft/1.5 m) or plasma (2D6x10 M.D., 15 ft/4.6 m)', 1, 'Typically 5 miles (8 km); plasma and fragmentation 3 miles (4.8 km)', 'One at a time or volleys of two or four', '10', NULL, 'Anti-armor and anti-fortification, secondarily anti-monster and assault. A box launcher on a turret atop the communications suite, 360 degrees with a 45 degree vertical arc; slides down beside the suite when stowed. The pilot or the comms officer fires it.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-v36-beachmaster', 'ng-ex5-behemoth-explorer', 'ng-ex9-behemoth-super-explorer', 'ng-v50-bigfoot');
SELECT 'their 54 locations are in' AS assertion, count(*) AS got, 54 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-v36-beachmaster', 'ng-ex5-behemoth-explorer', 'ng-ex9-behemoth-super-explorer', 'ng-v50-bigfoot');
SELECT 'their 15 weapon entries are in' AS assertion, count(*) AS got, 15 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-v36-beachmaster', 'ng-ex5-behemoth-explorer', 'ng-ex9-behemoth-super-explorer', 'ng-v50-bigfoot');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-v36-beachmaster', 'ng-ex5-behemoth-explorer', 'ng-ex9-behemoth-super-explorer', 'ng-v50-bigfoot') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

